"""
Tool execution abstraction for localized tool handling.
Encapsulates dynamic import, instantiation, execution, and error handling.
"""

import importlib
import inspect
from typing import Any, Dict, Union
from rich.console import Console
from rich.panel import Panel
import json

from tools.base import BaseTool
from config import Config


class ToolExecutor:
    """
    Centralized executor for all tool operations.
    Handles:
    - Dynamic module loading
    - Tool instantiation via BaseTool
    - Structured error handling
    - Result formatting
    """

    def __init__(self):
        self.console = Console()

    def execute_tool(self, tool_name: str, tool_input: Dict[str, Any]) -> Dict[str, Any]:
        """
        Execute a tool by name with the given input.

        Args:
            tool_name: Name of the tool to execute (e.g., 'fileeditortool')
            tool_input: Dictionary of arguments to pass to the tool

        Returns:
            Dict with keys:
            - success: bool
            - output: Any (tool's return value or error message)
            - tool_name: str
        """
        # Validate inputs early
        if not tool_name or not isinstance(tool_name, str):
            return self._create_error_result(
                tool_name=tool_name or "unknown",
                message="Invalid tool name: must be a non-empty string"
            )

        if not isinstance(tool_input, dict):
            return self._create_error_result(
                tool_name=tool_name,
                message="Invalid tool input: must be a dictionary"
            )

        try:
            # Dynamically import the tool module
            module = importlib.import_module(f"tools.{tool_name}")

            # Find and instantiate the tool class
            tool_instance = self._find_tool_instance_in_module(module, tool_name)

            if not tool_instance:
                return self._create_error_result(
                    tool_name=tool_name,
                    message=f"Tool class not found in module tools.{tool_name}"
                )

            # Execute the tool
            result = tool_instance.execute(**tool_input)

            # Format result for consistent handling
            formatted_result = self._format_result(result)

            return {
                "success": True,
                "output": formatted_result,
                "tool_name": tool_name
            }

        except ImportError as e:
            return self._create_error_result(
                tool_name=tool_name,
                message=f"Failed to import tool module: {str(e)}"
            )
        except Exception as e:
            return self._create_error_result(
                tool_name=tool_name,
                message=f"Tool execution error: {str(e)}"
            )

    def _find_tool_instance_in_module(self, module, expected_tool_name: str) -> Union[BaseTool, None]:
        """
        Find a tool instance matching the expected name in a module.
        """
        for name, obj in inspect.getmembers(module):
            if (inspect.isclass(obj) and 
                issubclass(obj, BaseTool) and 
                obj != BaseTool):
                try:
                    candidate = obj()
                    if candidate.name == expected_tool_name:
                        return candidate
                except Exception:
                    continue
        return None

    def _create_error_result(self, tool_name: str, message: str) -> Dict[str, Any]:
        """Create a standardized error result."""
        error_panel = Panel(
            f"[bold red]❌ Tool '{tool_name}' failed[/bold red]\n{message}",
            border_style="red",
            title="Tool Execution Error"
        )
        self.console.print(error_panel)
        return {
            "success": False,
            "output": message,
            "tool_name": tool_name
        }

    def _format_result(self, result: Any) -> Any:
        """
        Format the tool result for consistent output handling.
        """
        if isinstance(result, str):
            return result
        elif isinstance(result, (dict, list)):
            return result
        else:
            return str(result)


def clean_data_for_display(data: Any) -> Any:
    """
    Clean data for display by handling various data types
    and removing/replacing large content like base64 strings.

    This is the centralized version of the previous Assistant._clean_data_for_display logic.
    """
    if isinstance(data, str):
        try:
            # Try to parse as JSON first
            parsed_data = json.loads(data)
            return clean_parsed_data(parsed_data)
        except json.JSONDecodeError:
            # If it's a long string, check for base64 patterns
            if len(data) > 1000 and ';base64,' in data:
                return "[base64 data omitted]"
            return data
    elif isinstance(data, dict):
        return clean_parsed_data(data)
    else:
        return data


def clean_parsed_data(data: Any) -> Any:
    """
    Recursively clean parsed JSON/dict data, handling nested structures
    and replacing large data with placeholders.

    This is the centralized version of the previous Assistant._clean_parsed_data logic.
    """
    if isinstance(data, dict):
        cleaned = {}
        for key, value in data.items():
            # Handle image data in various formats
            if key in ['data', 'image', 'source'] and isinstance(value, str):
                if len(value) > 1000 and (';base64,' in value or value.startswith('data:')):
                    cleaned[key] = "[base64 data omitted]"
                else:
                    cleaned[key] = value
            else:
                cleaned[key] = clean_parsed_data(value)
        return cleaned
    elif isinstance(data, list):
        return [clean_parsed_data(item) for item in data]
    elif isinstance(data, str) and len(data) > 1000 and ';base64,' in data:
        return "[base64 data omitted]"
    return data
